(2040828, 280725, 43434, '<td valign="top">I think this is a fantastic shot, the letdown for me is in the cropping.</td>', 'I think this is a fantastic shot, the letdown for me is in the cropping.', '2006-01-16 02:57:41.000000', NULL, 1),
(2040831, 280689, 42984, '<td valign="top">Now that is good! Great light values and the shallow dof is superb. Having the OOF foreground is what so many have missed.</td>', 'Now that is good! Great light values and the shallow dof is superb. Having the OOF foreground is what so many have missed.', '2006-01-16 02:58:35.000000', NULL, 1),
