(2041814, 281543, 34938, '<td valign="top">not sure how this fits in to the subject, but I''ll take your word for the fact that it is a candid in a crowd</td>', 'not sure how this fits in to the subject, but I''ll take your word for the fact that it is a candid in a crowd', '2006-01-16 09:36:09.000000', NULL, 1),
(2041817, 280589, 34938, '<td valign="top">nice shot</td>', 'nice shot', '2006-01-16 09:36:33.000000', NULL, 1),
(2041821, 281950, 34938, '<td valign="top">beautifully singled out...great colour and atmosphere</td>', 'beautifully singled out...great colour and atmosphere', '2006-01-16 09:36:59.000000', NULL, 1),
(2041823, 281266, 16241, '<td valign="top">so funny!</td>', 'so funny!', '2006-01-16 09:37:17.000000', NULL, 1),
(2041825, 280615, 34938, '<td valign="top">great shot...love her reflection...wonderful sharpness and DOF...well done</td>', 'great shot...love her reflection...wonderful sharpness and DOF...well done', '2006-01-16 09:37:52.000000', NULL, 1),
(2041829, 280547, 34938, '<td valign="top">very well edited...you''re about the only one so far who took advantage of the advancd editing opportunity...good composition</td>', 'very well edited...you''re about the only one so far who took advantage of the advancd editing opportunity...good composition', '2006-01-16 09:38:48.000000', NULL, 1),
(2041833, 280689, 34938, '<td valign="top">great capture...perhaps would have liked to have seen more of the fish...</td>', 'great capture...perhaps would have liked to have seen more of the fish...', '2006-01-16 09:40:05.000000', NULL, 1),
(2041840, 280253, 34938, '<td valign="top">the shot is nice and I like the B &amp; W and the soft focus...composition could do with a little crop in the top because her head is too close to the centre for me</td>', 'the shot is nice and I like the B & W and the soft focus...composition could do with a little crop in the top because her head is too close to the centre for me', '2006-01-16 09:41:26.000000', NULL, 1),
(2041844, 281861, 34938, '<td valign="top">good job</td>', 'good job', '2006-01-16 09:41:44.000000', NULL, 1),
(2041846, 279654, 34938, '<td valign="top">more of a portrait than a candid...but nonetheless a great one...crisp and sharp, I love the contrast</td>', 'more of a portrait than a candid...but nonetheless a great one...crisp and sharp, I love the contrast', '2006-01-16 09:42:30.000000', NULL, 1),
(2041849, 280904, 34938, '<td valign="top">great work, cute kid, the picture tells a great story</td>', 'great work, cute kid, the picture tells a great story', '2006-01-16 09:43:13.000000', NULL, 1),
(2041854, 281122, 34938, '<td valign="top">great shot with great DOF...for composition''s sake, would have like to have seen more of the guy on the left (or not at all)...he seems to throw things off balance a bit. Lighting is great</td>', 'great shot with great DOF...for composition''s sake, would have like to have seen more of the guy on the left (or not at all)...he seems to throw things off balance a bit. Lighting is great', '2006-01-16 09:44:57.000000', NULL, 1),
(2041857, 281806, 34938, '<td valign="top">a winner...this deserves to win...he''s singled out, he''s different from the rest, the DOF is great, there''s a great sense of atmosphere 9</td>', 'a winner...this deserves to win...he''s singled out, he''s different from the rest, the DOF is great, there''s a great sense of atmosphere 9', '2006-01-16 09:45:19.000000', NULL, 1),
(2041859, 280725, 16241, '<td valign="top">ah exquisite!</td>', 'ah exquisite!', '2006-01-16 09:45:29.000000', NULL, 1),
(2041883, 281059, 31885, '<td valign="top">Interesting Capture, but I think the focus is a little off.</td>', 'Interesting Capture, but I think the focus is a little off.', '2006-01-16 09:51:40.000000', NULL, 1),
(2041889, 281272, 31885, '<td valign="top">Nice one, I like the fact that you can still see the expressions on the faces of the children in the background, although they are out of focus.</td>', 'Nice one, I like the fact that you can still see the expressions on the faces of the children in the background, although they are out of focus.', '2006-01-16 09:54:05.000000', NULL, 1),
(2041894, 281257, 31885, '<td valign="top">Great colours! The artificial DOF does not work for me - the child and mom are in the same focal plane so it looks unnatural.</td>', 'Great colours! The artificial DOF does not work for me - the child and mom are in the same focal plane so it looks unnatural.', '2006-01-16 09:55:54.000000', NULL, 1),
(2041898, 281237, 31885, '<td valign="top">Good work, lovely lighting.</td>', 'Good work, lovely lighting.', '2006-01-16 09:56:47.000000', NULL, 1),
(2041912, 281231, 31885, '<td valign="top">Nice composition. I think the artificial DOF could have worked, but the soft edges on the girl''s jersey gives it away too much.</td>', 'Nice composition. I think the artificial DOF could have worked, but the soft edges on the girl''s jersey gives it away too much.', '2006-01-16 09:59:54.000000', NULL, 1),
(2041917, 281541, 31885, '<td valign="top">I think the light on the face is too harsh, hiding too much of the detail.</td>', 'I think the light on the face is too harsh, hiding too much of the detail.', '2006-01-16 10:02:08.000000', NULL, 1),
(2041933, 280760, 31885, '<td valign="top">I''m not sure if I like it or if the guy''s dark form is too dominating. Will have to come back...</td>', 'I''m not sure if I like it or if the guy''s dark form is too dominating. Will have to come back...', '2006-01-16 10:06:08.000000', NULL, 1),
(2041937, 280916, 31885, '<td valign="top">Good capture of the title! Nice soft lighting and good DOF.</td>', 'Good capture of the title! Nice soft lighting and good DOF.', '2006-01-16 10:07:12.000000', NULL, 1),
(2041944, 280288, 31885, '<td valign="top">Great expression!</td>', 'Great expression!', '2006-01-16 10:09:44.000000', NULL, 1),
(2041949, 279085, 31885, '<td valign="top">Good capture and composition. Good work on getting the even lighting on the faces. I don''t like the unnaturally soft faces.</td>', 'Good capture and composition. Good work on getting the even lighting on the faces. I don''t like the unnaturally soft faces.', '2006-01-16 10:12:29.000000', NULL, 1),
(2041954, 281941, 31885, '<td valign="top">Excellent, excellent!</td>', 'Excellent, excellent!', '2006-01-16 10:13:48.000000', NULL, 1),
(2041959, 281033, 31885, '<td valign="top">Great job, the reflection is just perfect.</td>', 'Great job, the reflection is just perfect.', '2006-01-16 10:15:59.000000', NULL, 1),
(2041964, 281266, 39184, '<td valign="top">He sure did single himself out, so maybe he should be scored instead of the photographer.  But then again, he also singled himself by not being in a crowd instead of following the details of the challenge either: "Use minimal depth-of-field to your advantage to help isolate your subject".<br/> <br/>My comments are the culmination of seeing so many photos in which the photographer seemed to cave in to the difficulties of meeting the details associated with the challenge.  I finally caved in and commented while viewing your entry, but the gist of my comments could be applied to the majority of entries.<br/> <br/>One thing that you definitely achieved was creativity. Outside of the challenge details, I like this shot.  I know it is difficult to achieve, but I would like to see less light in the background and more light on the cowboy''s face.</td>', 'He sure did single himself out, so maybe he should be scored instead of the photographer.  But then again, he also singled himself by not being in a crowd instead of following the details of the challenge either: "Use minimal depth-of-field to your advantage to help isolate your subject". My comments are the culmination of seeing so many photos in which the photographer seemed to cave in to the difficulties of meeting the details associated with the challenge.  I finally caved in and commented while viewing your entry, but the gist of my comments could be applied to the majority of entries. One thing that you definitely achieved was creativity. Outside of the challenge details, I like this shot.  I know it is difficult to achieve, but I would like to see less light in the background and more light on the cowboy''s face.', '2006-01-16 10:16:55.000000', NULL, 1),
(2041967, 279921, 31885, '<td valign="top">What is happening in the bottom right of the picture? I spoils an otherwise beautiful shot.</td>', 'What is happening in the bottom right of the picture? I spoils an otherwise beautiful shot.', '2006-01-16 10:17:12.000000', NULL, 1),
(2041975, 280404, 31885, '<td valign="top">Is this girl from Ipanema or Durban? Great lighting and DOF.</td>', 'Is this girl from Ipanema or Durban? Great lighting and DOF.', '2006-01-16 10:19:52.000000', NULL, 1),
(2041979, 281642, 2170, '<td valign="top">great lighting work here.</td>', 'great lighting work here.', '2006-01-16 10:20:27.000000', NULL, 1),
(2041987, 279654, 2170, '<td valign="top">this is a great shot, but i don''t see a crowd?</td>', 'this is a great shot, but i don''t see a crowd?', '2006-01-16 10:21:49.000000', NULL, 1),
(2041994, 280431, 2170, '<td valign="top">i think it hurts this shot that part of her face is hidden.</td>', 'i think it hurts this shot that part of her face is hidden.', '2006-01-16 10:23:07.000000', NULL, 1),
(2041999, 281793, 19982, '<td valign="top">Absolutely lovely image...  wish it were in the Best of 2005 challenge instead of the Singled Out challenge as I would have voted it much higher there.</td>', 'Absolutely lovely image...  wish it were in the Best of 2005 challenge instead of the Singled Out challenge as I would have voted it much higher there.', '2006-01-16 10:23:47.000000', NULL, 1),
(2042020, 280610, 2170, '<td valign="top">i don''t like the use of selective desaturation here.</td>', 'i don''t like the use of selective desaturation here.', '2006-01-16 10:28:00.000000', NULL, 1),
(2042024, 280404, 2170, '<td valign="top">this is a great photograph.  very well-done.</td>', 'this is a great photograph.  very well-done.', '2006-01-16 10:30:34.000000', NULL, 1),
