INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2042048, 280951, 38234, '<td valign="top">beautifully done and perfect title!</td>', 'beautifully done and perfect title!', '2006-01-16 10:35:16.000000', NULL, 1),
(2042051, 281879, 35545, '<td valign="top">IMHO this is a good picture, but not for this challenge.  The subject is supposed to be set out from a crowd.</td>', 'IMHO this is a good picture, but not for this challenge.  The subject is supposed to be set out from a crowd.', '2006-01-16 10:35:56.000000', NULL, 1),
(2042062, 281891, 35545, '<td valign="top">This is a good picture, but, IMHO, not for this challenge.  You are supposed to single the subject out from a crowd.  I''m afraid I don''t see the crowd.</td>', 'This is a good picture, but, IMHO, not for this challenge.  You are supposed to single the subject out from a crowd.  I''m afraid I don''t see the crowd.', '2006-01-16 10:38:00.000000', NULL, 1),
(2042071, 281537, 35545, '<td valign="top">This is a good picture, but, IMHO, not for this challenge.  You are supposed to single the subject out from a crowd.  I''m afraid I don''t see the crowd.</td>', 'This is a good picture, but, IMHO, not for this challenge.  You are supposed to single the subject out from a crowd.  I''m afraid I don''t see the crowd.', '2006-01-16 10:39:57.000000', NULL, 1),
(2042077, 280288, 38234, '<td valign="top">great expression you captured!</td>', 'great expression you captured!', '2006-01-16 10:41:29.000000', NULL, 1),
(2042079, 281734, 39184, '<td valign="top">Amazing coincidence that you were able to get a CANDID shot of someone wearing angel wings that look just like the wings in the blue ribbon winner titled "Angel Flew Too Close To The Ground" in the Oops! II challenge.</td>', 'Amazing coincidence that you were able to get a CANDID shot of someone wearing angel wings that look just like the wings in the blue ribbon winner titled "Angel Flew Too Close To The Ground" in the Oops! II challenge.', '2006-01-16 10:41:44.000000', NULL, 1),
(2042080, 279654, 35545, '<td valign="top">This is a good picture, but, IMHO, not for this challenge.  You are supposed to single the subject out from a crowd.  I''m afraid I don''t see the crowd.</td>', 'This is a good picture, but, IMHO, not for this challenge.  You are supposed to single the subject out from a crowd.  I''m afraid I don''t see the crowd.', '2006-01-16 10:41:46.000000', NULL, 1),
(2042092, 281613, 35545, '<td valign="top">Single-out a person in a crowd as your source of composition ...  This is really pushing it, a little too far IMHO.  You also need to put an apostrophe in the title.</td>', 'Single-out a person in a crowd as your source of composition ...  This is really pushing it, a little too far IMHO.  You also need to put an apostrophe in the title.', '2006-01-16 10:44:39.000000', NULL, 1),
(2042096, 281222, 38234, '<td valign="top">you did a great job singling him out but the light''s a bit hot</td>', 'you did a great job singling him out but the light''s a bit hot', '2006-01-16 10:45:05.000000', NULL, 1),
(2042102, 280288, 35545, '<td valign="top">To my eye, you haven''t used shallow depth of field to set off the subject from the background.</td>', 'To my eye, you haven''t used shallow depth of field to set off the subject from the background.', '2006-01-16 10:46:49.000000', NULL, 1),
(2042109, 280434, 34134, '<td valign="top">This is a GREAT photo. Excellent cropping. I like the faceless crowd around this poor soul.</td>', 'This is a GREAT photo. Excellent cropping. I like the faceless crowd around this poor soul.', '2006-01-16 10:47:27.000000', NULL, 1),
(2042121, 280434, 38234, '<td valign="top">great perspective which really adds to the theme intent!  great tones and composition - overall a compelling image - 10 from me</td>', 'great perspective which really adds to the theme intent!  great tones and composition - overall a compelling image - 10 from me', '2006-01-16 10:49:58.000000', NULL, 1),
(2042122, 281101, 35545, '<td valign="top">You''ve got shallow depth of field all right, but two of the boys are on the same plane.  I can''t see that you''ve singled out one individual.</td>', 'You''ve got shallow depth of field all right, but two of the boys are on the same plane.  I can''t see that you''ve singled out one individual.', '2006-01-16 10:49:58.000000', NULL, 1),
(2042135, 280610, 39184, '<td valign="top">With your careful use of DOF you managed to keep the crowd in focus. It appears that you were also able to make your subject stand out using selective desaturation.  Too bad that wasn''t in the challenge details.</td>', 'With your careful use of DOF you managed to keep the crowd in focus. It appears that you were also able to make your subject stand out using selective desaturation.  Too bad that wasn''t in the challenge details.', '2006-01-16 10:52:25.000000', NULL, 1),
(2042141, 280725, 50036, '<td valign="top">I can''t vote in this challenge, but this one is my favourite! Good luck!!</td>', 'I can''t vote in this challenge, but this one is my favourite! Good luck!!', '2006-01-16 10:52:48.000000', NULL, 1),
(2042143, 280610, 35545, '<td valign="top">YOu''ve used color to set off the subject, not shallow depth of field.</td>', 'YOu''ve used color to set off the subject, not shallow depth of field.', '2006-01-16 10:52:49.000000', NULL, 1),
(2042146, 281888, 35545, '<td valign="top">Single-out a person in a crowd as your source of composition//  Where''s the crowd.</td>', 'Single-out a person in a crowd as your source of composition//  Where''s the crowd.', '2006-01-16 10:53:47.000000', NULL, 1),
(2042152, 281543, 35545, '<td valign="top">Single-out a person in a crowd as your source of composition.  Where''s the crowd.  Where''s the shallow depth of field to set off the subject?</td>', 'Single-out a person in a crowd as your source of composition.  Where''s the crowd.  Where''s the shallow depth of field to set off the subject?', '2006-01-16 10:54:24.000000', NULL, 1),
(2042163, 280873, 35545, '<td valign="top">Single-out a person in a crowd as your source of composition... Where''s the crowd.  Where''s the shallow depth of field?</td>', 'Single-out a person in a crowd as your source of composition... Where''s the crowd.  Where''s the shallow depth of field?', '2006-01-16 10:55:55.000000', NULL, 1),
(2042175, 280576, 35545, '<td valign="top">Single-out a person in a crowd as your source of composition...  Where''s the crowd?</td>', 'Single-out a person in a crowd as your source of composition...  Where''s the crowd?', '2006-01-16 10:57:05.000000', NULL, 1),
(2042219, 281500, 35545, '<td valign="top">Single-out a person in a crowd as your source of composition..  Where''s the crowd.  Great use of depth of field, but an unappealing subject.</td>', 'Single-out a person in a crowd as your source of composition..  Where''s the crowd.  Great use of depth of field, but an unappealing subject.', '2006-01-16 11:00:42.000000', NULL, 1),
(2042264, 279671, 5728, '<td valign="top">Excellent idea, and well done!</td>', 'Excellent idea, and well done!', '2006-01-16 11:04:50.000000', NULL, 1),
(2042278, 280917, 34134, '<td valign="top">Creative!</td>', 'Creative!', '2006-01-16 11:06:17.000000', NULL, 1),
(2042337, 281272, 50695, '<td valign="top">One of my two 10s. I just love how he pops out of this busy composition, which is worthy of an abstract painting. And his gesture is fascinating, ambiguous, visceral, ethereal, everything...</td>', 'One of my two 10s. I just love how he pops out of this busy composition, which is worthy of an abstract painting. And his gesture is fascinating, ambiguous, visceral, ethereal, everything...', '2006-01-16 11:14:41.000000', NULL, 1),
(2042340, 281806, 50695, '<td valign="top">I love the drama of this shot. I feel like I''m watching the climactic scene in a musical. I also like the ambiguity of his expression. He seems to be ready for great joy or great tragedy. One of my two 10s.</td>', 'I love the drama of this shot. I feel like I''m watching the climactic scene in a musical. I also like the ambiguity of his expression. He seems to be ready for great joy or great tragedy. One of my two 10s.', '2006-01-16 11:15:20.000000', NULL, 1),
(2042411, 281122, 34134, '<td valign="top">Good shot!! It tells a story too!</td>', 'Good shot!! It tells a story too!', '2006-01-16 11:28:14.000000', NULL, 1),
(2042425, 280951, 34134, '<td valign="top">Good lighting. Rich color.</td>', 'Good lighting. Rich color.', '2006-01-16 11:30:10.000000', NULL, 1),
(2042432, 279671, 34134, '<td valign="top">GREAT capture.</td>', 'GREAT capture.', '2006-01-16 11:31:18.000000', NULL, 1),
(2042451, 281642, 34134, '<td valign="top">He''s near a knife. Time to leave. NOW!!  Good shot.</td>', 'He''s near a knife. Time to leave. NOW!!  Good shot.', '2006-01-16 11:34:55.000000', NULL, 1),
(2042462, 281327, 34134, '<td valign="top">Great expression. Good capture.</td>', 'Great expression. Good capture.', '2006-01-16 11:36:34.000000', NULL, 1),
(2042466, 281941, 34134, '<td valign="top">Good choice for B&amp;W!</td>', 'Good choice for B&W!', '2006-01-16 11:37:39.000000', NULL, 1),
(2042567, 281861, 6519, '<td valign="top">I assume that the DOF was done in post processing (but don''t worry, it makes no difference to my score). I rather like the way he seems to float in space.... looks like quite the character, too.</td>', 'I assume that the DOF was done in post processing (but don''t worry, it makes no difference to my score). I rather like the way he seems to float in space.... looks like quite the character, too.', '2006-01-16 11:57:04.000000', NULL, 1),
(2042590, 280951, 5112, '<td valign="top">Wow, I love this image!  ~10</td>', 'Wow, I love this image!  ~10', '2006-01-16 12:01:43.000000', NULL, 1),
(2042602, 279671, 34192, '<td valign="top">My favorite of the challenge.  eye contact means so much more than shallow depth of field to create a subject.  Extremely excellent capture.  tones very effective. 10</td>', 'My favorite of the challenge.  eye contact means so much more than shallow depth of field to create a subject.  Extremely excellent capture.  tones very effective. 10', '2006-01-16 12:05:14.000000', NULL, 1),
(2042610, 279671, 5112, '<td valign="top">Excellent!</td>', 'Excellent!', '2006-01-16 12:07:15.000000', NULL, 1),
(2042613, 281806, 45790, '<td valign="top">Good shot but bad spelling.</td>', 'Good shot but bad spelling.', '2006-01-16 12:07:58.000000', NULL, 1),
(2042646, 279769, 36981, '<td valign="top">My favorite!  This is a great image; I love how he''s isolated not only by the DOF, but also being (I think) the only man, and looking the other way.  The choice of B&amp;W feels perfect to me.</td>', 'My favorite!  This is a great image; I love how he''s isolated not only by the DOF, but also being (I think) the only man, and looking the other way.  The choice of B&W feels perfect to me.', '2006-01-16 12:20:35.000000', NULL, 1),
(2042651, 281033, 36981, '<td valign="top">One of the best, IMO.  The boy''s face is beautiful, and the feeling the B&amp;W gives is very serene.</td>', 'One of the best, IMO.  The boy''s face is beautiful, and the feeling the B&W gives is very serene.', '2006-01-16 12:20:50.000000', NULL, 1),
(2042653, 281806, 36981, '<td valign="top">What a fabulous capture!  He''s terrific, and the crowd is perfect.  The story is what most captures my imagination.</td>', 'What a fabulous capture!  He''s terrific, and the crowd is perfect.  The story is what most captures my imagination.', '2006-01-16 12:21:07.000000', NULL, 1),
