(2042684, 281921, 40370, '<td valign="top">I must admit I am looking for "faces" opposed to shoes or birds in this challenge, however your creative crowd of faces will get my vote.</td>', 'I must admit I am looking for "faces" opposed to shoes or birds in this challenge, however your creative crowd of faces will get my vote.', '2006-01-16 12:32:31.000000', NULL, 1),
