INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2045515, 281272, 46601, '<td valign="top">Great capture here ... takes a sec for it to really sink in, might have been better if the "others" were in a little softer focus ... great work!</td>', 'Great capture here ... takes a sec for it to really sink in, might have been better if the "others" were in a little softer focus ... great work!', '2006-01-16 21:54:39.000000', NULL, 1),
(2045516, 281593, 46601, '<td valign="top">great shot!</td>', 'great shot!', '2006-01-16 21:54:42.000000', NULL, 1),
(2045670, 279769, 26756, '<td valign="top">Fantastic shot.   I almost have to say though that the three women in back are so interesting, I''m looking in their direction too.  To really single him out I''ve have gone a bit more shallow with the dof, but I''ll give you a 9 anyway because the pic is really fantastic.</td>', 'Fantastic shot.   I almost have to say though that the three women in back are so interesting, I''m looking in their direction too.  To really single him out I''ve have gone a bit more shallow with the dof, but I''ll give you a 9 anyway because the pic is really fantastic.', '2006-01-16 22:32:03.000000', NULL, 1),
(2045676, 279671, 26756, '<td valign="top">Does not seem real, but if it is it''s quite amazing.  I imagine it''s a friend or relative of yours that you placed there for the effect.  Great idea and great execution.  Toning is perfect. 10</td>', 'Does not seem real, but if it is it''s quite amazing.  I imagine it''s a friend or relative of yours that you placed there for the effect.  Great idea and great execution.  Toning is perfect. 10', '2006-01-16 22:33:45.000000', NULL, 1),
(2045715, 279671, 6349, '<td valign="top">There''s the winner of the challenge.  10 and favorite.</td>', 'There''s the winner of the challenge.  10 and favorite.', '2006-01-16 22:42:46.000000', NULL, 1),
(2045717, 280404, 6349, '<td valign="top">I predict a ribbon for this one.  Great dof, subject, and tones. 10</td>', 'I predict a ribbon for this one.  Great dof, subject, and tones. 10', '2006-01-16 22:43:12.000000', NULL, 1),
(2045719, 280760, 6349, '<td valign="top">I hope this ribbons.  Deserves to.  10 and favorite.</td>', 'I hope this ribbons.  Deserves to.  10 and favorite.', '2006-01-16 22:43:38.000000', NULL, 1),
(2045723, 281266, 38648, '<td valign="top">I can''t wait to see just who submitted this one!  Bizzare, but got my attention.</td>', 'I can''t wait to see just who submitted this one!  Bizzare, but got my attention.', '2006-01-16 22:43:58.000000', NULL, 1),
(2045725, 281998, 6349, '<td valign="top">I love this photo.  Has a real vintage feel to it.  9</td>', 'I love this photo.  Has a real vintage feel to it.  9', '2006-01-16 22:44:03.000000', NULL, 1),
(2045808, 279654, 34154, '<td valign="top">so much wasted space on the top of the frame</td>', 'so much wasted space on the top of the frame', '2006-01-16 23:02:47.000000', NULL, 1),
(2045810, 281806, 34154, '<td valign="top">the blur just isn''t natural, nice idea though</td>', 'the blur just isn''t natural, nice idea though', '2006-01-16 23:03:53.000000', NULL, 1),
(2045815, 279671, 34154, '<td valign="top">i was really pissed off going through the challenge entries and seeing that everyone was relying on poorly executed post-work instead of creative photography. thank mahdi that this one popped up. normally it would really bother me that there is so much space on the top of the frame, but i love that his face is right in the center of the photo. nice work.</td>', 'i was really pissed off going through the challenge entries and seeing that everyone was relying on poorly executed post-work instead of creative photography. thank mahdi that this one popped up. normally it would really bother me that there is so much space on the top of the frame, but i love that his face is right in the center of the photo. nice work.', '2006-01-16 23:06:20.000000', NULL, 1),
