(2055188, 280689, 50641, '<td valign="top">Love his expression. Very James Spader! Like photo overall but might wish for more people or   ...some fish! ;-)</td>', 'Love his expression. Very James Spader! Like photo overall but might wish for more people or   ...some fish! ;-)', '2006-01-18 17:08:04.000000', NULL, 1),
(2055191, 281642, 50641, '<td valign="top">Wonderful humor in this shot.  Hope he had some too!</td>', 'Wonderful humor in this shot.  Hope he had some too!', '2006-01-18 17:08:32.000000', NULL, 1),
(2055196, 281356, 48890, '<td valign="top">The ball is nicely caught in the air, but the rest of the stuff in the frame is not very interesting.</td>', 'The ball is nicely caught in the air, but the rest of the stuff in the frame is not very interesting.', '2006-01-18 17:09:16.000000', NULL, 1),
(2055205, 281122, 48890, '<td valign="top">I really like how the people are situated in this shot.  The eye jumps in an unusual zig-zag trajectory.  I wish there was less DOF to isolate the guy in the right a little better.</td>', 'I really like how the people are situated in this shot.  The eye jumps in an unusual zig-zag trajectory.  I wish there was less DOF to isolate the guy in the right a little better.', '2006-01-18 17:10:45.000000', NULL, 1),
(2055206, 281101, 48890, '<td valign="top">I don''t think anything is really singled out here.</td>', 'I don''t think anything is really singled out here.', '2006-01-18 17:11:05.000000', NULL, 1),
(2055208, 279921, 50641, '<td valign="top">I like it, but what I really want to know is what that chick to the right is thinking ;-)</td>', 'I like it, but what I really want to know is what that chick to the right is thinking ;-)', '2006-01-18 17:11:19.000000', NULL, 1),
(2055216, 281500, 50641, '<td valign="top">Nice, but context  a little too blurry.</td>', 'Nice, but context  a little too blurry.', '2006-01-18 17:13:07.000000', NULL, 1),
(2055218, 280709, 48890, '<td valign="top">You were obviously trying to say something with this shot, but I am not getting it.  Composition wise, the piece of the arm chair in the right-hand corner does not add anything to the shot.  Also, the woman probably needs a little more room in the direction she is leaning.  I guess hte pillow is a bit singled-out, but insufficiently and I don''t understand what for.</td>', 'You were obviously trying to say something with this shot, but I am not getting it.  Composition wise, the piece of the arm chair in the right-hand corner does not add anything to the shot.  Also, the woman probably needs a little more room in the direction she is leaning.  I guess hte pillow is a bit singled-out, but insufficiently and I don''t understand what for.', '2006-01-18 17:13:30.000000', NULL, 1),
(2055219, 280683, 50641, '<td valign="top">Interesting frame and title.</td>', 'Interesting frame and title.', '2006-01-18 17:13:51.000000', NULL, 1),
(2055221, 281941, 48890, '<td valign="top">A nice shot, good use of DOF.</td>', 'A nice shot, good use of DOF.', '2006-01-18 17:14:03.000000', NULL, 1),
(2055230, 280883, 50641, '<td valign="top">Like she just found a cavity.  Funny title.</td>', 'Like she just found a cavity.  Funny title.', '2006-01-18 17:15:41.000000', NULL, 1),
(2055231, 281213, 48890, '<td valign="top">This shot is not composed carefully.  The body of the swinger in blue is missing a head, and the facial expression of the closest person is not interesting.  It''s a shame, with all these colourful lines added by the swings, this could be a more interesting composition.</td>', 'This shot is not composed carefully.  The body of the swinger in blue is missing a head, and the facial expression of the closest person is not interesting.  It''s a shame, with all these colourful lines added by the swings, this could be a more interesting composition.', '2006-01-18 17:15:50.000000', NULL, 1),
(2055235, 281901, 50641, '<td valign="top">Yow.  So he is the singled out one?  Creative take.</td>', 'Yow.  So he is the singled out one?  Creative take.', '2006-01-18 17:16:53.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2055236, 280462, 48890, '<td valign="top">She''s singled out, alright. :) I am not sure I like the motion blurs in this shot: I don''t think they were intentional.</td>', 'She''s singled out, alright. :) I am not sure I like the motion blurs in this shot: I don''t think they were intentional.', '2006-01-18 17:17:05.000000', NULL, 1),
(2055240, 280589, 48890, '<td valign="top">Nice, promissing composition, but I don''t think anything is singled-out here.</td>', 'Nice, promissing composition, but I don''t think anything is singled-out here.', '2006-01-18 17:17:49.000000', NULL, 1),
(2055241, 281589, 50641, '<td valign="top">I like the water droplets in the left top corner, but the clarity of her freckles strikes me as off.</td>', 'I like the water droplets in the left top corner, but the clarity of her freckles strikes me as off.', '2006-01-18 17:18:24.000000', NULL, 1),
(2055243, 279671, 50641, '<td valign="top">Ha!  Fun.</td>', 'Ha!  Fun.', '2006-01-18 17:19:07.000000', NULL, 1),
(2055246, 280777, 48890, '<td valign="top">I don''t understand who is singled out here: the boy or the girl?  The composition is not working for me.</td>', 'I don''t understand who is singled out here: the boy or the girl?  The composition is not working for me.', '2006-01-18 17:19:33.000000', NULL, 1),
