(2055251, 281555, 48890, '<td valign="top">She is singled out, but what makes this shot interesting?</td>', 'She is singled out, but what makes this shot interesting?', '2006-01-18 17:20:11.000000', NULL, 1),
(2055253, 281950, 50641, '<td valign="top">Wow that''s some super-bindi!  Nice shot.</td>', 'Wow that''s some super-bindi!  Nice shot.', '2006-01-18 17:21:10.000000', NULL, 1),
(2055256, 281990, 50641, '<td valign="top">Not baaad at all, in my book.</td>', 'Not baaad at all, in my book.', '2006-01-18 17:21:37.000000', NULL, 1),
(2055260, 281257, 50641, '<td valign="top">Hmm, doesn''t quite ring true with mom being so close, yet so blurred.  Nice try.</td>', 'Hmm, doesn''t quite ring true with mom being so close, yet so blurred.  Nice try.', '2006-01-18 17:22:26.000000', NULL, 1),
(2055271, 281543, 50641, '<td valign="top">Good title, funny expression, but I wish he were more singled out in the sense of being in a crowd.</td>', 'Good title, funny expression, but I wish he were more singled out in the sense of being in a crowd.', '2006-01-18 17:23:50.000000', NULL, 1),
(2055274, 281945, 50641, '<td valign="top">You think you know me butt you don''t.</td>', 'You think you know me butt you don''t.', '2006-01-18 17:24:46.000000', NULL, 1),
(2055279, 280873, 48890, '<td valign="top">I don''t really see anything singled-out in this photograph.  Anyways, hardly an interesting photograph to anyone outside of your family.</td>', 'I don''t really see anything singled-out in this photograph.  Anyways, hardly an interesting photograph to anyone outside of your family.', '2006-01-18 17:25:38.000000', NULL, 1),
(2055285, 281870, 50641, '<td valign="top">Nice change-up from the norm.  Looks like a difficult shot to get.  Unless the effect''s <i>entirely</i> postprocessed.</td>', 'Nice change-up from the norm.  Looks like a difficult shot to get.  Unless the effect''s entirely postprocessed.', '2006-01-18 17:26:42.000000', NULL, 1),
(2055288, 280725, 48890, '<td valign="top">Nicely done, DOF well used.  The dead in the middle composition is a tad boring, which is my only remark to this very interesting shot.</td>', 'Nicely done, DOF well used.  The dead in the middle composition is a tad boring, which is my only remark to this very interesting shot.', '2006-01-18 17:27:13.000000', NULL, 1),
(2055289, 280404, 48890, '<td valign="top">A very nice, dynamic shot, well done.</td>', 'A very nice, dynamic shot, well done.', '2006-01-18 17:27:24.000000', NULL, 1),
(2055384, 281990, 48890, '<td valign="top">The cow is not singled out by means of shallow DOF, but only because it raised its head, so I don''t think that this shot fits into the contest very well.  Otherwise a nice shot.</td>', 'The cow is not singled out by means of shallow DOF, but only because it raised its head, so I don''t think that this shot fits into the contest very well.  Otherwise a nice shot.', '2006-01-18 17:55:59.000000', NULL, 1),
(2055390, 281491, 48890, '<td valign="top">Nicely exposed shot, but it''s a bit boring: what''s in this shot ot interest me?</td>', 'Nicely exposed shot, but it''s a bit boring: what''s in this shot ot interest me?', '2006-01-18 17:57:37.000000', NULL, 1),
(2055391, 280689, 48890, '<td valign="top">Nice capture, I like the facial expression of the salesman.  The composition is a bit cluttered and uninteresting, though.</td>', 'Nice capture, I like the facial expression of the salesman.  The composition is a bit cluttered and uninteresting, though.', '2006-01-18 17:58:56.000000', NULL, 1),
(2055398, 281805, 48890, '<td valign="top">I don''t think that the DOF is thin enough for the girl in the front to be singled out.  The composition is a bit lacking: the legs in the right side of the shot clearly should not be there.</td>', 'I don''t think that the DOF is thin enough for the girl in the front to be singled out.  The composition is a bit lacking: the legs in the right side of the shot clearly should not be there.', '2006-01-18 18:01:11.000000', NULL, 1),
(2055399, 281085, 48890, '<td valign="top">I don''t think anyone is singled out here.  IMO not a very interesting shot.</td>', 'I don''t think anyone is singled out here.  IMO not a very interesting shot.', '2006-01-18 18:01:39.000000', NULL, 1),
(2055400, 281976, 48890, '<td valign="top">Nice pose of the subject, but I would crop out most of the clutter from the frame.</td>', 'Nice pose of the subject, but I would crop out most of the clutter from the frame.', '2006-01-18 18:02:31.000000', NULL, 1),
(2055402, 280625, 48890, '<td valign="top">Nice moment, but I don''t think anything is singled out here.</td>', 'Nice moment, but I don''t think anything is singled out here.', '2006-01-18 18:03:04.000000', NULL, 1),
(2055403, 281501, 48890, '<td valign="top">So who''s singled out here?  The composition lacks emphasis.</td>', 'So who''s singled out here?  The composition lacks emphasis.', '2006-01-18 18:03:36.000000', NULL, 1),
(2055408, 279819, 48890, '<td valign="top">The DOF is working to single out the guy with the magazine, but I think that the composition is not a lucky one.  THe face of the guy sitting to the left of the main subject is smashed into the magazine.  The face of the guy sitting the closest to the photographer mostly covers all of the face of the main subject.</td>', 'The DOF is working to single out the guy with the magazine, but I think that the composition is not a lucky one.  THe face of the guy sitting to the left of the main subject is smashed into the magazine.  The face of the guy sitting the closest to the photographer mostly covers all of the face of the main subject.', '2006-01-18 18:04:59.000000', NULL, 1),
(2055410, 281998, 48890, '<td valign="top">I don''t think DOF is thin enough here. A nice subject, thogh, but the middle-of-the-frame composition is a bit boring.</td>', 'I don''t think DOF is thin enough here. A nice subject, thogh, but the middle-of-the-frame composition is a bit boring.', '2006-01-18 18:06:20.000000', NULL, 1),
