(2057676, 281806, 48890, '<td valign="top">A very nice shot.  I am not giving it a full mark because I think that the DOF is not sufficiently used here to isolate the main subject, which was one of the requirements.</td>', 'A very nice shot.  I am not giving it a full mark because I think that the DOF is not sufficiently used here to isolate the main subject, which was one of the requirements.', '2006-01-19 02:57:03.000000', NULL, 1),
(2057677, 281500, 48890, '<td valign="top">Nice shot.  The composition is a bit boring, with the main subject in the middle.</td>', 'Nice shot.  The composition is a bit boring, with the main subject in the middle.', '2006-01-19 02:57:55.000000', NULL, 1),
(2057680, 280904, 48890, '<td valign="top">Not sure who''s singled out here.  Seems to me the whole shot is blurry.</td>', 'Not sure who''s singled out here.  Seems to me the whole shot is blurry.', '2006-01-19 02:58:40.000000', NULL, 1),
(2057682, 280883, 48890, '<td valign="top">Nice use of DOF.  Can''t say the shot grabs me, though, so I''m not giving it a full mark.</td>', 'Nice use of DOF.  Can''t say the shot grabs me, though, so I''m not giving it a full mark.', '2006-01-19 02:59:26.000000', NULL, 1),
(2057686, 281515, 48890, '<td valign="top">DOF isolation is working, but the composition is not very thoughful.  IMO you should have included more of the motorcycle in the frame, and *not* included somebody''s shoulder on the left, and somebody''s elbow on the right.</td>', 'DOF isolation is working, but the composition is not very thoughful.  IMO you should have included more of the motorcycle in the frame, and *not* included somebody''s shoulder on the left, and somebody''s elbow on the right.', '2006-01-19 03:00:57.000000', NULL, 1),
(2057687, 280950, 48890, '<td valign="top">Nice portrait, good use of DOF.  Sorry, the shot doesn''t grab me, so not a full mark.</td>', 'Nice portrait, good use of DOF.  Sorry, the shot doesn''t grab me, so not a full mark.', '2006-01-19 03:01:45.000000', NULL, 1),
(2057688, 281995, 48890, '<td valign="top">I don''t seem much DOF isolation here, and the shot is not interesting both composition- and story-wise.</td>', 'I don''t seem much DOF isolation here, and the shot is not interesting both composition- and story-wise.', '2006-01-19 03:02:29.000000', NULL, 1),
