(2057692, 281618, 48890, '<td valign="top">I don''t see any DOF isolation (a requirement) here; in fact DOF is infinity in this shot.  A quite nice shot otherwise.</td>', 'I don''t see any DOF isolation (a requirement) here; in fact DOF is infinity in this shot.  A quite nice shot otherwise.', '2006-01-19 03:04:04.000000', NULL, 1),
(2057693, 281444, 48890, '<td valign="top">There is a very slight DOF isolation here, but, IMO, a rather boring shot.</td>', 'There is a very slight DOF isolation here, but, IMO, a rather boring shot.', '2006-01-19 03:04:45.000000', NULL, 1),
(2057695, 280431, 48890, '<td valign="top">The shot would be much nicer if we could see here face, IMO.  Also, DOF could be used more to isolate her from the rest of the people.</td>', 'The shot would be much nicer if we could see here face, IMO.  Also, DOF could be used more to isolate her from the rest of the people.', '2006-01-19 03:05:33.000000', NULL, 1),
(2057697, 281950, 48890, '<td valign="top">Some use of DOF (although could be used more), but I don''t like motion blur and the compositoin is a bit messy.</td>', 'Some use of DOF (although could be used more), but I don''t like motion blur and the compositoin is a bit messy.', '2006-01-19 03:06:29.000000', NULL, 1),
(2057701, 281183, 48890, '<td valign="top">You caught a nice moment, but the DOF isolation is barely used here, and the composition is not good, with the couple standing dead in front of the waterfall.</td>', 'You caught a nice moment, but the DOF isolation is barely used here, and the composition is not good, with the couple standing dead in front of the waterfall.', '2006-01-19 03:07:37.000000', NULL, 1),
