(2057897, 281593, 18080, '<td valign="top">My only 10 of this challenge.<br/>Blue ribbon for sure...<br/>Well i hope so.<br/>Good luck on this perfect shot.<br/> <br/>Kev</td>', 'My only 10 of this challenge.Blue ribbon for sure...Well i hope so.Good luck on this perfect shot. Kev', '2006-01-19 04:54:00.000000', NULL, 1),
(2058118, 280547, 7756, '<td valign="top">Excellent. Top 3 image</td>', 'Excellent. Top 3 image', '2006-01-19 06:03:40.000000', NULL, 1),
(2058212, 281257, 18207, '<td valign="top">Isn''t it strange that the boy is in focus as well as the shore 2-3meters behind him and the mother standing next to her son is not? Should take care of an object''s distance from the camera when giving a false small-DOF feeling during PP.</td>', 'Isn''t it strange that the boy is in focus as well as the shore 2-3meters behind him and the mother standing next to her son is not? Should take care of an object''s distance from the camera when giving a false small-DOF feeling during PP.', '2006-01-19 06:44:59.000000', NULL, 1),
(2058289, 281941, 18207, '<td valign="top">Heh, girl in the background, smiling straight into the camera. :)</td>', 'Heh, girl in the background, smiling straight into the camera. :)', '2006-01-19 07:19:17.000000', NULL, 1),
(2058295, 281888, 18207, '<td valign="top">It''s a portrait with too much light from the side (but well balanced shadows to keep details there). Still, she''s not "singled out".<br/>                             /gazdi, DNMC-nazi/</td>', 'It''s a portrait with too much light from the side (but well balanced shadows to keep details there). Still, she''s not "singled out".                             /gazdi, DNMC-nazi/', '2006-01-19 07:21:01.000000', NULL, 1),
