(2060684, 281352, 36006, '<td valign="top">Nice attempt, dead on b&amp;w, nice dof, interesting light, overall very good stuff</td>', 'Nice attempt, dead on b&w, nice dof, interesting light, overall very good stuff', '2006-01-19 18:28:39.000000', NULL, 1),
