(2060710, 281500, 47378, '<td valign="top">Reminds me of Stone Cold Steve Austin (but much smaller)...</td>', 'Reminds me of Stone Cold Steve Austin (but much smaller)...', '2006-01-19 18:34:34.000000', NULL, 1),
(2060722, 280431, 36006, '<td valign="top">Nice attempt, color very nice, light ok, texture nice, would of liked to see an expression instead of fabric, <i>almost</i>a DNMC, nice dof, overall just nice.</td>', 'Nice attempt, color very nice, light ok, texture nice, would of liked to see an expression instead of fabric, almosta DNMC, nice dof, overall just nice.', '2006-01-19 18:36:32.000000', NULL, 1),
(2060728, 281537, 36006, '<td valign="top">nice attempt, great color, very nice light, just a bit soft, overall very nice</td>', 'nice attempt, great color, very nice light, just a bit soft, overall very nice', '2006-01-19 18:38:22.000000', NULL, 1),
(2060741, 279085, 36006, '<td valign="top">Nice attempt, not too convincing however for this challenge, ok color, excellent capture, light a bit harsh, blacks ok, whites blown, overall just ok</td>', 'Nice attempt, not too convincing however for this challenge, ok color, excellent capture, light a bit harsh, blacks ok, whites blown, overall just ok', '2006-01-19 18:43:02.000000', NULL, 1),
