(2072701, 280725, 1031, '<td valign="top">While even in my crazy part of the world this look might well be considered "exotic" and not conservative : )<br/> <br/>Nice lighting, detail, expressive model.</td>', 'While even in my crazy part of the world this look might well be considered "exotic" and not conservative : ) Nice lighting, detail, expressive model.', '2006-01-22 23:20:28.000000', NULL, 1),
(2072712, 281491, 1031, '<td valign="top">Pictures of kids concentrating seem to have a certain look to them ... I have one of my son which my mom took which is one of my favorites.</td>', 'Pictures of kids concentrating seem to have a certain look to them ... I have one of my son which my mom took which is one of my favorites.', '2006-01-22 23:22:34.000000', NULL, 1),
(2072725, 280760, 1031, '<td valign="top">Four modes of transportation in one frame -- well-done! Hope the bus didn''t run over the car ... the "gritty" look works for this urban setting.</td>', 'Four modes of transportation in one frame -- well-done! Hope the bus didn''t run over the car ... the "gritty" look works for this urban setting.', '2006-01-22 23:25:18.000000', NULL, 1),
