INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2072784, 280589, 1031, '<td valign="top">An unusual "perspective" on the challenge. Nice lighting.<br/> <br/>For some reason, it reminds me of the TV series <i>The Prisoner</i>, where there were scenes of hooded men confronting the protagonists ... your empty (but reserved) chairs likewise can represent anyone, so long as they are in opposition to your subject.</td>', 'An unusual "perspective" on the challenge. Nice lighting. For some reason, it reminds me of the TV series The Prisoner, where there were scenes of hooded men confronting the protagonists ... your empty (but reserved) chairs likewise can represent anyone, so long as they are in opposition to your subject.', '2006-01-22 23:35:49.000000', NULL, 1),
(2072795, 280930, 29009, '<td valign="top">Focal point does not take up enough space in the frame.</td>', 'Focal point does not take up enough space in the frame.', '2006-01-22 23:37:39.000000', NULL, 1),
(2072804, 280689, 1031, '<td valign="top">Good job isolating the subject''s face in the dark field. I might have cropped from the bottom to an exact square, and to lessen the amount of bright foreground so it frames the face but dosn''t compete with it for attention.</td>', 'Good job isolating the subject''s face in the dark field. I might have cropped from the bottom to an exact square, and to lessen the amount of bright foreground so it frames the face but dosn''t compete with it for attention.', '2006-01-22 23:39:17.000000', NULL, 1),
(2072806, 281237, 45000, '<td valign="top">Beautiful lighting....</td>', 'Beautiful lighting....', '2006-01-22 23:39:47.000000', NULL, 1),
(2072812, 281950, 1031, '<td valign="top">Nice action shot under what looks like difficult lighting conditions.</td>', 'Nice action shot under what looks like difficult lighting conditions.', '2006-01-22 23:40:37.000000', NULL, 1),
(2072823, 281806, 1031, '<td valign="top">So how hard did it rain?</td>', 'So how hard did it rain?', '2006-01-22 23:43:27.000000', NULL, 1),
(2072824, 279671, 45000, '<td valign="top">Wow...if this doesn''t win blue...I will be amazed.  Absolutely and utterly stunning.  I love it....lightyears ahead of the rest of the entries.</td>', 'Wow...if this doesn''t win blue...I will be amazed.  Absolutely and utterly stunning.  I love it....lightyears ahead of the rest of the entries.', '2006-01-22 23:43:27.000000', NULL, 1),
(2072840, 281806, 29009, '<td valign="top">An interesting shot, but the DOF seems off.  Subject almost appears cut/pasted from another shot.  Effect is not believable (given the woman not in a raincoat), although focal point has indeed been singled out.<br/> <br/>Edited to add:  Well, I''ve never been so pleased to have been wrong in an assessment!  Congratulations, Skiprow!  <br/><br/><i>Message edited by author 2006-01-23 00:21:39.</i></td>', 'An interesting shot, but the DOF seems off.  Subject almost appears cut/pasted from another shot.  Effect is not believable (given the woman not in a raincoat), although focal point has indeed been singled out. Edited to add:  Well, I''ve never been so pleased to have been wrong in an assessment!  Congratulations, Skiprow!  ', '2006-01-22 23:47:02.000000', '2006-01-23 00:21:39.000000', 1),
(2072846, 280883, 30861, '<td valign="top">The more I see of this one, the more I like it! That''s a very cool expression, and there''s a crispness vs. bokeh thing going on here that appeals. WHAT is she thinking? Is her boyfriend late? Love the reversed whisp of hair also. Bumping you for good luck.</td>', 'The more I see of this one, the more I like it! That''s a very cool expression, and there''s a crispness vs. bokeh thing going on here that appeals. WHAT is she thinking? Is her boyfriend late? Love the reversed whisp of hair also. Bumping you for good luck.', '2006-01-22 23:48:03.000000', NULL, 1),
(2072848, 280434, 29009, '<td valign="top">Very powerful image here - perspective is fantastic.  Black and white treatment works well.</td>', 'Very powerful image here - perspective is fantastic.  Black and white treatment works well.', '2006-01-22 23:48:20.000000', NULL, 1),
(2072851, 281593, 30861, '<td valign="top">I like this more the more I look at it. Lovely colors, great expression.</td>', 'I like this more the more I look at it. Lovely colors, great expression.', '2006-01-22 23:48:42.000000', NULL, 1),
